#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

static int is_prime(uint64_t n) {
    if (n < 2) return 0;
    static const uint64_t bases[] = {2, 3, 5, 7, 11, 13};
    // small prime divisibility check
    for (size_t i = 0; i < sizeof(bases)/sizeof(bases[0]); ++i) {
        if (n == bases[i]) return 1;
        if (n % bases[i] == 0) return 0;
    }
    // write n-1 = d * 2^s with d odd
    uint64_t d = n - 1;
    int s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        ++s;
    }
    for (size_t i = 0; i < sizeof(bases)/sizeof(bases[0]); ++i) {
        uint64_t a = bases[i];
        if (a >= n) continue; // base larger than n is not needed
        // compute a^d mod n using 128‑bit intermediate to avoid overflow
        __uint128_t result = 1;
        __uint128_t base = a % n;
        uint64_t exp = d;
        while (exp) {
            if (exp & 1) result = (result * base) % n;
            base = (base * base) % n;
            exp >>= 1;
        }
        uint64_t x = (uint64_t)result;
        if (x == 1 || x == n - 1) continue;
        int r;
        for (r = 1; r < s; ++r) {
            __uint128_t xx = (__uint128_t)x * x % n;
            x = (uint64_t)xx;
            if (x == n - 1) break;
        }
        if (r == s) return 0; // composite
    }
    return 1; // probably prime (deterministic for the range used)
}

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr;
    uint64_t n = strtoll(argv[1], &endptr, 10);
    if (endptr == argv[1]) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 0xBFA17DC6ULL) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (is_prime(n))
        puts("PRIME");
    else
        puts("NOT_PRIME");
    return 0;
}
